import React, { useState, useEffect, useRef } from 'react';
import Axios from 'axios';
import { Chart, registerables } from 'chart.js';
import './course.css';

Chart.register(...registerables);

function CourseSearch() {
  const [data, setData] = useState([]);
  const [selectedCourse, setSelectedCourse] = useState('');
  const [selectedYear, setSelectedYear] = useState('');
  const [courses, setCourses] = useState([]);
  const [years, setYears] = useState([]);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState('');
  const chartRef = useRef(null);
  const chartInstanceRef = useRef(null);
  const yearChartInstanceRef = useRef(null);

  const fetchAllData = async () => {
    setLoading(true);
    setMessage('');
    try {
      const response = await Axios.get('http://localhost:3002/details');
      const users = response.data.users || [];
      setData(users);

      const uniqueCourses = [...new Set(users.map((user) => user.course))].sort();
      setCourses(uniqueCourses);

      const uniqueYears = [...new Set(users.map((user) => user.year))].sort();
      setYears(uniqueYears);

      setLoading(false);

      if (chartInstanceRef.current) chartInstanceRef.current.destroy();
      if (yearChartInstanceRef.current) yearChartInstanceRef.current.destroy();
    } catch (error) {
      setLoading(false);
      setMessage('Error fetching data. Please try again.');
      console.error('Error fetching all data:', error);
    }
  };

  const fetchCourseYearData = async (course, year) => {
    setLoading(true);
    setMessage('');
    try {
      const response = await Axios.post('http://localhost:3002/course', { course, year });
      const users = response.data.users || [];
      setData(users);
      setLoading(false);

      if (users.length === 0) {
        setMessage('No records found for this course and year.');
      } else {
        requestAnimationFrame(() => updateChart(users, course, year));
      }
    } catch (error) {
      setLoading(false);
      setMessage('Error searching data. Please try again.');
      console.error('Error searching course and year:', error);
    }
  };

  const updateChart = (users, course, year) => {
    try {
      if (chartInstanceRef.current) chartInstanceRef.current.destroy();

      const ctx = chartRef.current?.getContext('2d');
      if (!ctx) return;

      const districtData = {};
      users.forEach((user) => {
        const count = Number.isFinite(user.Students) ? user.Students : 0;
        const key = `${user.campus || 'N/A'} - ${user.district || 'Unknown'}`;
        districtData[key] = (districtData[key] || 0) + count;
      });

      const labels = Object.keys(districtData);
      const studentCounts = Object.values(districtData);

      chartInstanceRef.current = new Chart(ctx, {
        type: 'bar',
        data: {
          labels,
          datasets: [{
            label: 'Number of Students',
            data: studentCounts,
            backgroundColor: 'rgba(37, 99, 235, 0.6)',
            borderColor: 'rgba(37, 99, 235, 1)',
            borderWidth: 1
          }]
        },
        options: {
          responsive: true,
          scales: {
            y: {
              beginAtZero: true,
              title: { display: true, text: 'Students' }
            },
            x: {
              title: { display: true, text: 'Campus - District' }
            }
          },
          plugins: {
            legend: { display: false },
            title: {
              display: true,
              text: `Students in ${course} (${year}) by Campus-District`,
              font: { size: 16 }
            }
          }
        }
      });
    } catch (error) {
      console.error('Chart rendering error:', error);
    }
  };

  const updateYearChart = async (course) => {
    try {
      const response = await Axios.get('http://localhost:3002/details');
      const allUsers = response.data.users || [];

      const filtered = allUsers.filter((user) => user.course === course);

      const yearData = {};
      filtered.forEach((user) => {
        const year = user.year;
        const count = Number.isFinite(user.Students) ? user.Students : 0;
        if (year) {
          yearData[year] = (yearData[year] || 0) + count;
        }
      });

      const labels = Object.keys(yearData).sort();
      const counts = labels.map((year) => yearData[year]);

      if (yearChartInstanceRef.current) yearChartInstanceRef.current.destroy();

      const ctx = document.getElementById('yearChart')?.getContext('2d');
      if (!ctx) return;

      yearChartInstanceRef.current = new Chart(ctx, {
        type: 'line',
        data: {
          labels,
          datasets: [{
            label: `Yearly Students in ${course} (All Campuses)`,
            data: counts,
            fill: false,
            borderColor: 'rgba(75, 192, 192, 1)',
            tension: 0.2
          }]
        },
        options: {
          responsive: true,
          scales: {
            y: {
              beginAtZero: true,
              title: {
                display: true,
                text: 'Students'
              }
            },
            x: {
              title: {
                display: true,
                text: 'Year'
              }
            }
          },
          plugins: {
            title: {
              display: true,
              text: `Students in ${course} Over the Years`,
              font: { size: 16 }
            },
            legend: {
              display: true,
              position: 'top'
            }
          }
        }
      });
    } catch (error) {
      console.error('Error generating year-wise chart:', error);
    }
  };

  const handleCourseChange = (event) => {
    const course = event.target.value;
    setSelectedCourse(course);
    if (course === '' && selectedYear === '') {
      fetchAllData();
    } else {
      fetchCourseYearData(course, selectedYear);
      if (selectedYear === '') {
        updateYearChart(course);
      } else if (yearChartInstanceRef.current) {
        yearChartInstanceRef.current.destroy();
      }
    }
  };

  const handleYearChange = (event) => {
    const year = event.target.value;
    setSelectedYear(year);
    if (selectedCourse === '' && year === '') {
      fetchAllData();
    } else {
      fetchCourseYearData(selectedCourse, year);
      if (selectedCourse && year === '') {
        updateYearChart(selectedCourse);
      } else if (yearChartInstanceRef.current) {
        yearChartInstanceRef.current.destroy();
      }
    }
  };

  useEffect(() => {
    fetchAllData();
    return () => {
      if (chartInstanceRef.current) chartInstanceRef.current.destroy();
      if (yearChartInstanceRef.current) yearChartInstanceRef.current.destroy();
    };
  }, []);

  return (
    <div className="app-container">
      <div className="content-container">
        <div className="course-search-card">
          <h2 className="title">Course Search</h2>

          <div className="form-group">
            <label htmlFor="course">Select Course</label>
            <select
              id="course"
              value={selectedCourse}
              onChange={handleCourseChange}
              disabled={loading}
              className="course-select"
            >
              <option value="">All Courses</option>
              {courses.map((course, index) => (
                <option key={index} value={course}>{course}</option>
              ))}
            </select>
          </div>

          <div className="form-group">
            <label htmlFor="year">Select Year</label>
            <select
              id="year"
              value={selectedYear}
              onChange={handleYearChange}
              disabled={loading}
              className="course-select"
            >
              <option value="">All Years</option>
              {years.map((year, index) => (
                <option key={index} value={year}>{year}</option>
              ))}
            </select>
          </div>

          {message && (
            <div className={`message ${message.includes('Error') ? 'error' : 'info'}`}>
              {message}
            </div>
          )}

          {loading ? (
            <div className="loading">Loading...</div>
          ) : (
            <div className="table-container">
              <table className="data-table">
                <thead>
                  <tr>
                    <th>District</th>
                    <th>Stream & Subjects</th>
                    <th>Course</th>
                    <th>Campus</th>
                    <th>Z-Range</th>
                    <th>Students</th>
                    <th>Year</th>
                  </tr>
                </thead>
                <tbody>
                  {data.length > 0 ? (
                    data.map((row) => (
                      <tr key={row._id}>
                        <td>{row.district}</td>
                        <td>
                          <div>{row.stream}</div>
                          <div>Subject 1: {row.subject1}</div>
                          <div>Subject 2: {row.subject2}</div>
                          <div>Subject 3: {row.subject3}</div>
                        </td>
                        <td>{row.course}</td>
                        <td>{row.campus}</td>
                        <td>{row.zValue1} - {row.zValue2}</td>
                        <td>{row.Students ?? 0}</td>
                        <td>{row.year}</td>
                      </tr>
                    ))
                  ) : (
                    <tr>
                      <td colSpan="7" style={{ textAlign: 'center' }}>No data available</td>
                    </tr>
                  )}
                </tbody>
              </table>
            </div>
          )}

          {selectedCourse && !loading && data.length > 0 && (
            <>
              <div className="chart-container">
                <canvas ref={chartRef} style={{ width: '100%', height: '400px' }}></canvas>
              </div>
              {selectedYear === '' && (
                <div className="chart-container">
                  <canvas id="yearChart" style={{ width: '100%', height: '400px' }}></canvas>
                </div>
              )}
            </>
          )}
        </div>
      </div>
    </div>
  );
}

export default CourseSearch;
